<?php $edit=first('SELECT * FROM routes WHERE id=? AND archived=0',[(int)($_GET['edit']??0)]);$editSteps=$edit?query('SELECT * FROM route_steps WHERE route_id=? ORDER BY position',[$edit['id']]):[];?>
<section class="card"><h2><?=$edit?'Новая версия маршрута':'Создать технологический маршрут'?></h2><p>Предшественники: 0 — исходная партия; пусто — предыдущий этап; несколько номеров через запятую — объединение потоков. Если несколько этапов имеют одного предшественника, они делят его остаток. После перестановки проверьте номера связей.</p><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="route_create"><input type="hidden" name="back" value="routes"><input type="hidden" name="previous_id" value="<?=(int)($edit['id']??0)?>"><label>Название маршрута</label><input name="name" required value="<?=h($edit['name']??'')?>"><div class="route-graph-toolbar"><button type="button" id="graph-layout">Авторасстановка</button><span id="graph-status" role="status">Выберите источник, затем нажмите на вход операции.</span></div><div id="route-graph" style="overflow:auto;border:1px solid #94a3b8;min-height:320px;position:relative"></div><div id="route-builder"></div><template id="route-template"><fieldset><legend>Этап</legend><label>Название этапа</label><input data-step-name required><label>Предшественники</label><input data-step-parents placeholder="Например: 1,2"><label>Норматив, секунд на деталь</label><input type="number" min="0" data-step-norm value="0" required><label>Инструкция</label><textarea data-step-instruction></textarea><label>Допустимые станки</label><select data-step-machines multiple required><?php foreach($machines as $m):?><option value="<?=$m['id']?>"><?=h($m['name'])?></option><?php endforeach;?></select><button type="button" data-up>Выше</button><button type="button" data-remove>Удалить этап</button></fieldset></template><button type="button" id="add-step">+ Этап</button><button class="primary">Сохранить маршрут</button></form><script type="application/json" id="route-edit-data"><?=json_encode($editSteps,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><script src="assets/route-graph.js" defer></script></section>
<section class="card"><h2>Маршруты и версии</h2><?php foreach($routes as $r):?><h3><?=h($r['name'])?> · №<?=$r['id']?> <?=$r['archived']?'(архив)':''?></h3><?php if(!$r['archived']):?><a href="?page=routes&amp;edit=<?=$r['id']?>">Редактировать</a><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="route_archive"><input type="hidden" name="back" value="routes"><input type="hidden" name="route_id" value="<?=$r['id']?>"><button>Архивировать</button></form><?php endif;?><ol><?php foreach(query('SELECT * FROM route_steps WHERE route_id=? ORDER BY position',[$r['id']]) as $s):?><li><?=h($s['name'])?> — вход <?=h($s['parents']??($s['position']-1))?>; норматив <?=$s['norm_seconds']?> сек.</li><?php endforeach;?></ol><?php endforeach;?></section>